
namespace CustomerSupport.Mvc.Models.Api
{
    // The eight structured values generated by the AI model.
    public sealed class TicketAIAnalysis
    {
        public string Problem { get; set; } = string.Empty;

        public List<string> ActionsTried { get; set; } = [];

        public string NextStep { get; set; } = string.Empty;

        public string Sentiment { get; set; } = string.Empty;

        public string? SuggestedCategory
        {
            get; set;
        }

        public string? SuggestedPriority
        {
            get; set;
        }

        public string? ConfirmedResolutionDate
        {
            get; set;
        }

        public bool RequiresHumanReview
        {
            get; set;
        }
    }
}
